import * as THREE from "three";

export const meta = {
  name: "Koala on Eucalyptus Stand",
  description:
    "A low-poly koala clinging to a vertical eucalyptus branch mounted on a weighted base, with fluffy ears, dark nose, gripping paws, claws, leaves and bark markings.",
};

export default function createKoala(): THREE.Group {
  const root = new THREE.Group();
  root.name = "KoalaOnStand";

  const mat = (color: number, rough = 0.9) =>
    new THREE.MeshStandardMaterial({ color, roughness: rough, flatShading: true });

  const fur = mat(0x8d9096);
  const furLight = mat(0xc9c9c4);
  const furDark = mat(0x5f6368);
  const nose = mat(0x1b1b1d, 0.5);
  const clawM = mat(0x2b2623, 0.6);
  const bark = mat(0x8a6a4c);
  const barkDark = mat(0x5b4430);
  const leafM = mat(0x5f8a5a);
  const leafM2 = mat(0x7aa36b);
  const baseM = mat(0x4a3b2e);
  const eyeM = mat(0x0c0c0c, 0.3);

  const add = (
    geo: THREE.BufferGeometry,
    m: THREE.Material,
    pos: [number, number, number],
    scale: [number, number, number] = [1, 1, 1],
    rot: [number, number, number] = [0, 0, 0],
    parent: THREE.Object3D = root
  ) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(...pos);
    mesh.scale.set(...scale);
    mesh.rotation.set(...rot);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
  };

  // ---- Stand base ----
  add(new THREE.CylinderGeometry(0.32, 0.38, 0.06, 8), baseM, [0, 0.03, 0]);
  add(new THREE.CylinderGeometry(0.26, 0.3, 0.05, 8), barkDark, [0, 0.085, 0]);
  // Support feet (weighted)
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
    add(new THREE.BoxGeometry(0.1, 0.03, 0.1), barkDark, [Math.cos(a) * 0.3, 0.015, Math.sin(a) * 0.3], [1, 1, 1], [0, -a, 0]);
  }

  // ---- Eucalyptus trunk (vertical branch) ----
  const trunkH = 1.5;
  const trunk = add(new THREE.CylinderGeometry(0.05, 0.065, trunkH, 7), bark, [0, 0.11 + trunkH / 2, 0]);
  trunk.name = "Trunk";
  // Bark markings: peeling strips and knots
  for (let i = 0; i < 9; i++) {
    const a = i * 2.1;
    const y = 0.3 + i * 0.15;
    add(new THREE.BoxGeometry(0.015, 0.16, 0.012), barkDark, [Math.cos(a) * 0.058, y, Math.sin(a) * 0.058], [1, 1, 1], [0, -a, (i % 2 ? 0.1 : -0.1)]);
  }
  for (let i = 0; i < 4; i++) {
    const a = i * 1.7 + 0.5;
    add(new THREE.SphereGeometry(0.02, 5, 4), barkDark, [Math.cos(a) * 0.055, 0.45 + i * 0.35, Math.sin(a) * 0.055]);
  }

  // Side branches with leaves
  const leafGeo = new THREE.SphereGeometry(0.06, 5, 3);
  const branchDefs: [number, number, number][] = [
    [1.45, 0.5, 0.3],
    [1.2, 2.6, -0.4],
    [1.62, 4.1, 0.5],
    [0.55, 3.4, -0.3],
  ];
  branchDefs.forEach(([y, a, tilt], bi) => {
    const len = 0.32;
    const br = new THREE.Group();
    br.position.set(0, y, 0);
    br.rotation.y = a;
    root.add(br);
    add(new THREE.CylinderGeometry(0.008, 0.016, len, 5), bark, [len / 2 * Math.cos(tilt), len / 2 * Math.sin(tilt), 0], [1, 1, 1], [0, 0, Math.PI / 2 + tilt], br);
    for (let k = 0; k < 4; k++) {
      const t = 0.3 + k * 0.22;
      const lx = len * t * 1.4;
      const ly = Math.sin(tilt) * lx;
      const side = k % 2 ? 1 : -1;
      add(leafGeo, k % 2 ? leafM : leafM2, [lx, ly - 0.02, side * 0.04], [1.9, 0.18, 0.7], [side * 0.3, 0, tilt - 0.4 * side], br);
    }
    add(leafGeo, leafM, [len * 1.35, Math.sin(tilt) * len * 1.35, 0], [2.2, 0.18, 0.8], [0, 0, tilt - 0.3], br);
    if (bi === 0) {
      // crown leaves at the top
      add(leafGeo, leafM2, [0, 0.12, 0.02], [0.4, 3, 0.7], [0.2, 0, 0.3], br);
    }
  });
  // Top crown
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    add(leafGeo, i % 2 ? leafM : leafM2, [Math.cos(a) * 0.08, 1.64, Math.sin(a) * 0.08], [0.4, 3.2, 0.7], [Math.sin(a) * 0.5, a, Math.cos(a) * 0.5]);
  }

  // ---- Koala ----
  const koala = new THREE.Group();
  koala.name = "Koala";
  // Clings on the +z side of the trunk, hugging it, facing +z
  koala.position.set(0, 0.62, 0.0);
  root.add(koala);

  const sph = (r: number) => new THREE.SphereGeometry(r, 8, 6);
  const trunkR = 0.06;

  // Body: stout, upright, pear-shaped
  add(sph(0.15), fur, [0, 0.2, trunkR + 0.12], [1, 1.35, 0.9], [-0.08, 0, 0], koala);
  add(sph(0.13), furLight, [0, 0.17, trunkR + 0.24], [0.85, 1.1, 0.35], [0, 0, 0], koala); // belly
  add(sph(0.16), furDark, [0, 0.0, trunkR + 0.12], [1.05, 0.8, 0.95], [0, 0, 0], koala); // rump

  // Head: large, broad
  const head = new THREE.Group();
  head.position.set(0, 0.5, trunkR + 0.2);
  head.rotation.x = 0.1;
  koala.add(head);
  add(sph(0.12), fur, [0, 0, 0], [1.15, 1, 1], [0, 0, 0], head);
  add(sph(0.07), furLight, [0, -0.04, 0.075], [1.1, 0.8, 0.8], [0, 0, 0], head); // muzzle
  // Big dark nose
  add(sph(0.036), nose, [0, 0.0, 0.135], [1.2, 1.5, 0.8], [0, 0, 0], head);
  // Mouth line
  add(new THREE.BoxGeometry(0.05, 0.006, 0.01), furDark, [0, -0.07, 0.125], [1, 1, 1], [0, 0, 0], head);
  // Eyes (small, close-set)
  for (const s of [-1, 1]) {
    add(sph(0.014), eyeM, [s * 0.055, 0.03, 0.105], [1, 1.1, 0.7], [0, 0, 0], head);
    add(sph(0.004), furLight, [s * 0.053, 0.036, 0.116], [1, 1, 1], [0, 0, 0], head);
    // Fluffy round ears
    add(sph(0.075), fur, [s * 0.12, 0.09, -0.01], [1, 1.1, 0.5], [0, s * 0.5, s * 0.2], head);
    add(sph(0.058), furLight, [s * 0.125, 0.09, 0.015], [1, 1.1, 0.4], [0, s * 0.5, s * 0.2], head);
    add(sph(0.03), furLight, [s * 0.1, 0.17, -0.005], [1, 1, 0.6], [0, s * 0.4, 0], head); // tuft
  }

  // ---- Limbs gripping the trunk ----
  const limb = (
    shoulder: [number, number, number],
    paw: [number, number, number],
    r: number,
    m: THREE.Material
  ) => {
    const a = new THREE.Vector3(...shoulder);
    const b = new THREE.Vector3(...paw);
    const d = b.clone().sub(a);
    const len = d.length();
    const mid = a.clone().add(b).multiplyScalar(0.5);
    const mesh = add(new THREE.CylinderGeometry(r * 0.8, r, len, 6), m, [mid.x, mid.y, mid.z], [1, 1, 1], [0, 0, 0], koala);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize());
    add(sph(r * 1.1), m, shoulder, [1, 1, 1], [0, 0, 0], koala);
  };

  const paw = (pos: [number, number, number], s: number, up: boolean) => {
    add(sph(0.04), furDark, pos, [1.1, 0.8, 1], [0, 0, 0], koala);
    // Claws wrap around trunk, two opposed digit groups
    for (let i = 0; i < 3; i++) {
      const dx = (i - 1) * 0.022;
      add(new THREE.ConeGeometry(0.008, 0.045, 4), clawM, [pos[0] + dx + s * 0.03, pos[1] + (up ? 0.02 : -0.02), pos[2] - 0.045], [1, 1, 1], [-Math.PI / 2, 0, s * 0.5], koala);
    }
    for (let i = 0; i < 2; i++) {
      add(new THREE.ConeGeometry(0.007, 0.04, 4), clawM, [pos[0] - s * 0.045 + (i - 0.5) * 0.02, pos[1], pos[2] - 0.05], [1, 1, 1], [-Math.PI / 2, 0, -s * 0.6], koala);
    }
  };

  for (const s of [-1, 1]) {
    // Forelimbs reach up around the trunk
    const sh: [number, number, number] = [s * 0.14, 0.38, trunkR + 0.14];
    const fp: [number, number, number] = [s * 0.05, 0.5, trunkR + 0.01];
    limb(sh, fp, 0.04, fur);
    paw(fp, s, true);
    // Hind legs bent, feet gripping lower
    const hh: [number, number, number] = [s * 0.14, 0.0, trunkR + 0.14];
    const hk: [number, number, number] = [s * 0.17, -0.08, trunkR + 0.2];
    const hf: [number, number, number] = [s * 0.05, -0.12, trunkR + 0.01];
    limb(hh, hk, 0.05, furDark);
    limb(hk, hf, 0.04, furDark);
    paw(hf, s, false);
  }

  // Small stub tail tuft
  add(sph(0.04), furLight, [0, -0.08, trunkR + 0.3], [1, 0.8, 1], [0, 0, 0], koala);

  // Chest fur ruffles
  for (let i = 0; i < 4; i++) {
    add(new THREE.ConeGeometry(0.03, 0.06, 4), furLight, [(i - 1.5) * 0.05, 0.42, trunkR + 0.25], [1, 1, 1], [Math.PI / 2 + 0.3, 0, 0], koala);
  }

  return root;
}
